import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import {
    PlusIcon, PencilIcon, TrashIcon, MagnifyingGlassIcon,
    FunnelIcon, Squares2X2Icon, ListBulletIcon, ArchiveBoxIcon
} from '@heroicons/react/24/outline';
import toast from 'react-hot-toast';
import productService from '../../services/productService';
import StatCard from '../../components/ui/StatCard';
import SectionCard from '../../components/ui/SectionCard';
import StatusBadge from '../../components/ui/StatusBadge';
import EmptyState from '../../components/ui/EmptyState';
import Pagination from '../../components/ui/Pagination';
import Modal from '../../components/ui/Modal';
import PageHeader from '../../components/ui/PageHeader';
import { Package, DollarSign, AlertTriangle, TrendingUp } from 'lucide-react';

const ProductManagement = () => {
    const [search, setSearch] = useState('');
    const [page, setPage] = useState(1);
    const [viewMode, setViewMode] = useState('table');
    const [editingProduct, setEditingProduct] = useState(null);
    const [showForm, setShowForm] = useState(false);
    const [deleteConfirm, setDeleteConfirm] = useState(null);
    const queryClient = useQueryClient();

    const { data, isLoading } = useQuery({
        queryKey: ['products', { search, page }],
        queryFn: () => productService.getAllProducts({ search, page, limit: 12 })
    });

    const deleteMutation = useMutation({
        mutationFn: productService.deleteProduct,
        onSuccess: () => {
            toast.success('Product deleted');
            queryClient.invalidateQueries(['products']);
            setDeleteConfirm(null);
        },
    });

    const products = data?.data || [];
    const pagination = data?.pagination;

    const stats = {
        total: products.length,
        totalValue: products.reduce((sum, p) => sum + (p.price * p.quantity), 0),
        lowStock: products.filter(p => p.quantity <= 5 && p.quantity > 0).length,
        outOfStock: products.filter(p => p.quantity === 0).length,
    };

    return (
        <div className="space-y-6">
            <PageHeader
                icon={Package}
                title="Product Management"
                description="Manage your product inventory and catalog"
                actions={
                    <button
                        onClick={() => { setEditingProduct(null); setShowForm(true); }}
                        className="flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-brand-700 to-brand-900 text-white rounded-xl hover:from-brand-800 hover:to-brand-950 transition-all font-semibold shadow-lg shadow-brand-500/25 text-sm"
                    >
                        <PlusIcon className="w-5 h-5" />
                        Add Product
                    </button>
                }
            />

            {/* Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Total Products" value={stats.total} icon={Package} color="navy" loading={isLoading} />
                <StatCard label="Inventory Value" value={`$${stats.totalValue.toLocaleString()}`} icon={DollarSign} color="emerald" loading={isLoading} />
                <StatCard label="Low Stock" value={stats.lowStock} icon={AlertTriangle} color="gold" loading={isLoading} />
                <StatCard label="Out of Stock" value={stats.outOfStock} icon={TrendingUp} color="rose" loading={isLoading} />
            </div>

            {/* Search & Filters */}
            <div className="bg-white dark:bg-brand-900 rounded-2xl border border-slate-200 dark:border-brand-700 shadow-card p-1.5">
                <div className="flex flex-col lg:flex-row gap-1.5">
                    <div className="relative flex-1">
                        <MagnifyingGlassIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                        <input
                            type="text"
                            placeholder="Search products by name or SKU..."
                            value={search}
                            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                            className="w-full pl-12 pr-4 py-3 bg-slate-50 dark:bg-brand-800 border border-slate-200 dark:border-brand-700 rounded-xl focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500 focus:bg-white dark:focus:bg-brand-900 transition-all text-sm"
                        />
                    </div>
                    <div className="flex gap-2">
                        <button
                            onClick={() => setViewMode(viewMode === 'table' ? 'grid' : 'table')}
                            className="px-4 py-3 border border-slate-200 dark:border-brand-700 rounded-xl hover:bg-slate-50 dark:hover:bg-brand-800 transition text-slate-600 dark:text-slate-400"
                        >
                            {viewMode === 'table' ? <Squares2X2Icon className="w-5 h-5" /> : <ListBulletIcon className="w-5 h-5" />}
                        </button>
                    </div>
                </div>
            </div>

            {/* Products List */}
            <SectionCard title="Products" subtitle={`${pagination?.total || 0} total products`}>
                {isLoading ? (
                    <div className="space-y-3">
                        {[...Array(5)].map((_, i) => (
                            <div key={i} className="animate-pulse flex items-center gap-4 py-3">
                                <div className="h-12 w-12 bg-slate-200 dark:bg-brand-700 rounded-xl" />
                                <div className="flex-1 space-y-2">
                                    <div className="h-4 w-40 bg-slate-200 dark:bg-brand-700 rounded" />
                                    <div className="h-3 w-24 bg-slate-200 dark:bg-brand-700 rounded" />
                                </div>
                            </div>
                        ))}
                    </div>
                ) : products.length === 0 ? (
                    <EmptyState
                        icon={ArchiveBoxIcon}
                        title="No products found"
                        description={search ? 'Try adjusting your search terms.' : 'Add your first product to get started.'}
                        searchTerm={search}
                        onClear={() => setSearch('')}
                        action={() => { setEditingProduct(null); setShowForm(true); }}
                        actionLabel="Add Product"
                    />
                ) : viewMode === 'table' ? (
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-slate-100 dark:divide-brand-700">
                            <thead>
                                <tr className="bg-slate-50/50 dark:bg-brand-800/30">
                                    <th className="px-6 py-4 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Product</th>
                                    <th className="px-6 py-4 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">SKU</th>
                                    <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">Price</th>
                                    <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">Quantity</th>
                                    <th className="px-6 py-4 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">Status</th>
                                    <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-brand-700">
                                {products.map((product, idx) => (
                                    <motion.tr
                                        key={product.id}
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        transition={{ delay: idx * 0.02 }}
                                        className="hover:bg-brand-50/30 dark:hover:bg-brand-800/20 transition-colors group"
                                    >
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className="h-10 w-10 rounded-xl bg-slate-100 dark:bg-brand-800 flex items-center justify-center overflow-hidden">
                                                    {product.imageUrl ? (
                                                        <img src={product.imageUrl} alt={product.name} className="h-full w-full object-cover" />
                                                    ) : (
                                                        <Package className="w-5 h-5 text-slate-400" />
                                                    )}
                                                </div>
                                                <span className="text-sm font-semibold text-brand-800 dark:text-white">{product.name}</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-sm text-slate-500 font-mono">{product.sku}</td>
                                        <td className="px-6 py-4 text-sm font-bold text-right">${product.price?.toFixed(2)}</td>
                                        <td className="px-6 py-4 text-sm text-right">{product.quantity}</td>
                                        <td className="px-6 py-4 text-center">
                                            <StatusBadge status={product.stockStatus?.status} label={product.stockStatus?.label} size="sm" />
                                        </td>
                                        <td className="px-6 py-4 text-right opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="flex items-center justify-end gap-1">
                                                <button
                                                    onClick={() => { setEditingProduct(product); setShowForm(true); }}
                                                    className="p-2 text-slate-400 hover:text-brand-600 transition-colors rounded-lg hover:bg-slate-100 dark:hover:bg-brand-800"
                                                >
                                                    <PencilIcon className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => setDeleteConfirm(product)}
                                                    className="p-2 text-slate-400 hover:text-rose-600 transition-colors rounded-lg hover:bg-slate-100 dark:hover:bg-brand-800"
                                                >
                                                    <TrashIcon className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </td>
                                    </motion.tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {products.map((product, idx) => (
                            <motion.div
                                key={product.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: idx * 0.03 }}
                                whileHover={{ y: -3 }}
                                className="group bg-white dark:bg-brand-900 rounded-2xl border border-slate-200 dark:border-brand-700 shadow-card overflow-hidden hover:shadow-elevated hover:border-brand-300 dark:hover:border-brand-600 transition-all duration-300 cursor-pointer"
                            >
                                <div className="h-1.5 bg-gradient-to-r from-brand-600 to-brand-800" />
                                <div className="p-5">
                                    <div className="flex items-start gap-3 mb-3">
                                        <div className="h-14 w-14 rounded-xl bg-slate-100 dark:bg-brand-800 flex items-center justify-center overflow-hidden flex-shrink-0">
                                            {product.imageUrl ? (
                                                <img src={product.imageUrl} alt={product.name} className="h-full w-full object-cover" />
                                            ) : (
                                                <Package className="w-6 h-6 text-slate-400" />
                                            )}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <p className="font-semibold text-brand-800 dark:text-white truncate">{product.name}</p>
                                            <p className="text-xs text-slate-500 font-mono">{product.sku}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center justify-between">
                                        <span className="text-lg font-bold text-brand-800 dark:text-white">${product.price?.toFixed(2)}</span>
                                        <StatusBadge status={product.stockStatus?.status} label={product.stockStatus?.label} size="sm" />
                                    </div>
                                    <div className="flex items-center justify-between mt-2 pt-2 border-t border-slate-100 dark:border-brand-700">
                                        <span className="text-xs text-slate-500">Qty: {product.quantity}</span>
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => { setEditingProduct(product); setShowForm(true); }} className="p-1.5 text-slate-400 hover:text-brand-600 rounded-lg hover:bg-slate-100">
                                                <PencilIcon className="w-4 h-4" />
                                            </button>
                                            <button onClick={() => setDeleteConfirm(product)} className="p-1.5 text-slate-400 hover:text-rose-600 rounded-lg hover:bg-slate-100">
                                                <TrashIcon className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        ))}
                    </div>
                )}

                <Pagination pagination={pagination} onPageChange={setPage} />
            </SectionCard>

            {/* Product Form Modal */}
            <ProductFormModal
                isOpen={showForm}
                onClose={() => { setShowForm(false); setEditingProduct(null); }}
                product={editingProduct}
                onSuccess={() => {
                    queryClient.invalidateQueries(['products']);
                    setShowForm(false);
                    setEditingProduct(null);
                }}
            />

            {/* Delete Confirmation */}
            <Modal
                isOpen={!!deleteConfirm}
                onClose={() => setDeleteConfirm(null)}
                title="Delete Product"
                subtitle="This action cannot be undone."
                size="sm"
                loading={deleteMutation.isLoading}
                footer={
                    <>
                        <button onClick={() => setDeleteConfirm(null)} className="px-5 py-2.5 border-2 border-slate-300 dark:border-brand-600 rounded-xl hover:bg-white dark:hover:bg-brand-800 transition font-medium text-sm">
                            Cancel
                        </button>
                        <button
                            onClick={() => deleteMutation.mutate(deleteConfirm.id)}
                            disabled={deleteMutation.isLoading}
                            className="px-6 py-2.5 bg-gradient-to-r from-rose-600 to-rose-700 text-white rounded-xl hover:from-rose-700 hover:to-rose-800 transition-all font-semibold text-sm shadow-lg shadow-rose-500/25"
                        >
                            {deleteMutation.isLoading ? 'Deleting...' : 'Delete Product'}
                        </button>
                    </>
                }
            >
                <p className="text-slate-600 dark:text-slate-400">
                    Are you sure you want to delete <strong className="text-brand-800 dark:text-white">"{deleteConfirm?.name}"</strong>? This action cannot be undone.
                </p>
            </Modal>
        </div>
    );
};

// Product Form Modal Component
const ProductFormModal = ({ isOpen, onClose, product, onSuccess }) => {
    const [form, setForm] = useState({ name: '', description: '', price: '', quantity: '', sku: '', imageUrl: '' });
    const [errors, setErrors] = useState({});
    const [loading, setLoading] = useState(false);

    React.useEffect(() => {
        if (product) {
            setForm({
                name: product.name || '',
                description: product.description || '',
                price: product.price?.toString() || '',
                quantity: product.quantity?.toString() || '',
                sku: product.sku || '',
                imageUrl: product.imageUrl || '',
            });
        } else {
            setForm({ name: '', description: '', price: '', quantity: '', sku: '', imageUrl: '' });
        }
        setErrors({});
    }, [product, isOpen]);

    const validate = () => {
        const errs = {};
        if (!form.name.trim()) errs.name = 'Product name is required';
        if (!form.price || parseFloat(form.price) < 0) errs.price = 'Valid price is required';
        if (!form.quantity || parseInt(form.quantity) < 0) errs.quantity = 'Valid quantity is required';
        setErrors(errs);
        return Object.keys(errs).length === 0;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!validate()) return;
        setLoading(true);
        try {
            const payload = { ...form, price: parseFloat(form.price), quantity: parseInt(form.quantity) };
            if (product) {
                await productService.updateProduct(product.id, payload);
                toast.success('Product updated');
            } else {
                await productService.createProduct(payload);
                toast.success('Product created');
            }
            onSuccess();
        } catch (error) {
            toast.error(error.response?.data?.message || 'Failed to save product');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title={product ? 'Edit Product' : 'Add Product'}
            subtitle="Fill in the product details below"
            loading={loading}
            footer={
                <>
                    <button onClick={onClose} className="px-5 py-2.5 border-2 border-slate-300 dark:border-brand-600 rounded-xl hover:bg-white dark:hover:bg-brand-800 transition font-medium text-sm">Cancel</button>
                    <button onClick={handleSubmit} disabled={loading} className="px-6 py-2.5 bg-gradient-to-r from-brand-700 to-brand-900 text-white rounded-xl hover:from-brand-800 hover:to-brand-950 transition-all font-semibold text-sm shadow-lg shadow-brand-500/25 disabled:opacity-50">
                        {loading ? 'Saving...' : product ? 'Update Product' : 'Create Product'}
                    </button>
                </>
            }
        >
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-1.5">Product Name <span className="text-rose-500">*</span></label>
                        <input type="text" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })}
                            className={`w-full px-4 py-3 border-2 rounded-xl text-sm transition-all ${errors.name ? 'border-rose-300 bg-rose-50' : 'border-slate-200 dark:border-brand-700 focus:border-brand-400 focus:ring-2 focus:ring-brand-500/20'} dark:bg-brand-800 dark:text-white`} />
                        {errors.name && <p className="text-xs text-rose-600 mt-1">{errors.name}</p>}
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-1.5">SKU</label>
                        <input type="text" value={form.sku} onChange={(e) => setForm({ ...form, sku: e.target.value })}
                            className="w-full px-4 py-3 border-2 border-slate-200 dark:border-brand-700 rounded-xl text-sm focus:border-brand-400 focus:ring-2 focus:ring-brand-500/20 dark:bg-brand-800 dark:text-white" />
                    </div>
                </div>
                <div>
                    <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-1.5">Description</label>
                    <textarea rows={3} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })}
                        className="w-full px-4 py-3 border-2 border-slate-200 dark:border-brand-700 rounded-xl text-sm focus:border-brand-400 focus:ring-2 focus:ring-brand-500/20 dark:bg-brand-800 dark:text-white resize-none" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-1.5">Price ($) <span className="text-rose-500">*</span></label>
                        <input type="number" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })}
                            className={`w-full px-4 py-3 border-2 rounded-xl text-sm transition-all ${errors.price ? 'border-rose-300 bg-rose-50' : 'border-slate-200 dark:border-brand-700 focus:border-brand-400 focus:ring-2 focus:ring-brand-500/20'} dark:bg-brand-800 dark:text-white`} />
                        {errors.price && <p className="text-xs text-rose-600 mt-1">{errors.price}</p>}
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-1.5">Quantity <span className="text-rose-500">*</span></label>
                        <input type="number" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })}
                            className={`w-full px-4 py-3 border-2 rounded-xl text-sm transition-all ${errors.quantity ? 'border-rose-300 bg-rose-50' : 'border-slate-200 dark:border-brand-700 focus:border-brand-400 focus:ring-2 focus:ring-brand-500/20'} dark:bg-brand-800 dark:text-white`} />
                        {errors.quantity && <p className="text-xs text-rose-600 mt-1">{errors.quantity}</p>}
                    </div>
                </div>
                <div>
                    <label className="block text-xs font-semibold text-brand-800 dark:text-slate-200 mb-1.5">Image URL</label>
                    <input type="url" value={form.imageUrl} onChange={(e) => setForm({ ...form, imageUrl: e.target.value })}
                        className="w-full px-4 py-3 border-2 border-slate-200 dark:border-brand-700 rounded-xl text-sm focus:border-brand-400 focus:ring-2 focus:ring-brand-500/20 dark:bg-brand-800 dark:text-white" placeholder="https://..." />
                </div>
            </form>
        </Modal>
    );
};

export default ProductManagement;
